// APlus Academy Core 1 acronym glossary. Every acronym used in the lessons, deep dives, and cheat sheet, plus those in questions.
// Rendered by the engine as hover links in tutorials and the cheat sheet (tip on hover, more on click) and as the
// cheat sheet's Acronyms section. Keys are matched as whole words, case-sensitive, plurals allowed. Original wording.
// Fields: full (what it stands for), tip (one sentence for the tooltip), more (the longer explanation; blank line = new paragraph).
window.FRA = window.FRA || {};
FRA.acronyms = {
  "12VHPWR": { full: "12 volt high power connector", tip: "The 16-pin connector on new graphics cards rated up to 600 W.", more: "12VHPWR replaces several 8-pin PCIe power plugs on high-end cards. It must be fully seated; a partly inserted plug overheats." },
  "3G": { full: "Third-generation cellular", tip: "The older mobile data generation, being switched off by carriers.", more: "3G networks are being retired, which strands devices that only support it." },
  "4G": { full: "Fourth-generation cellular", tip: "The LTE generation of mobile broadband.", more: "4G LTE is all-IP data at tens of megabits per second and remains the fallback under 5G." },
  "5G": { full: "Fifth-generation cellular", tip: "The current mobile network generation with higher speed and lower latency than LTE.", more: "5G uses new spectrum including millimeter wave for very high speeds over short range. Phones fall back to LTE where 5G is absent." },
  "802.11": { full: "IEEE 802.11", tip: "The family of Wi-Fi standards.", more: "802.11 defines wireless LANs. Its amendments are the generations you memorize: a, b, g, n (Wi-Fi 4), ac (Wi-Fi 5), ax (Wi-Fi 6 and 6E), and be (Wi-Fi 7), each with its bands, channel widths, and top speeds. Other amendments cover security (802.11i) and protected management frames (802.11w)." },
  "802.3af": { full: "IEEE 802.3af", tip: "The original Power over Ethernet standard: about 15.4 W at the switch, 12.95 W at the device.", more: "802.3af, plain PoE, powers phones, small cameras, and basic access points over two pairs of the data cable. If a device needs more than about 13 W, it needs 802.3at or 802.3bt." },
  "802.3at": { full: "IEEE 802.3at", tip: "PoE+: about 30 W at the switch, 25.5 W at the device.", more: "802.3at raised the power budget for devices such as multi-radio access points and pan-tilt cameras. A question that says the access point needs 25 watts is asking for at least 802.3at." },
  "802.3bt": { full: "IEEE 802.3bt", tip: "PoE++: 60 W (Type 3) or up to 90 W (Type 4) using all four pairs.", more: "802.3bt powers larger loads such as video conferencing units, LED lighting, and thin clients by using all four pairs of the cable. Type 3 delivers about 60 W and Type 4 about 90 W at the switch." },
  "AAA": { full: "Authentication, authorization, and accounting", tip: "Prove who you are, decide what you may do, record what you did.", more: "Authentication verifies identity (password, token, certificate), authorization decides which resources or commands are allowed, and accounting logs the session for auditing. RADIUS and TACACS+ are the protocols that deliver AAA to network devices." },
  "AAAA": { full: "Quad-A record", tip: "The DNS record that maps a name to an IPv6 address.", more: "An A record holds a 32-bit IPv4 address; an AAAA record is four times as long, holding a 128-bit IPv6 address, hence the name. A host that only has an A record cannot be reached by name from an IPv6-only client unless something such as DNS64 synthesizes a AAAA answer." },
  "AC": { full: "Alternating current", tip: "Mains power, which reverses direction 60 times a second in North America.", more: "The power supply converts AC from the wall to the DC a computer uses. Old CCFL backlights need high-voltage AC from an inverter. In the CBET course AC theory covers RMS voltage, frequency, and why 60 Hz current is dangerous." },
  "ACK": { full: "Acknowledgment", tip: "The TCP flag or message confirming data arrived.", more: "TCP acknowledges received segments so the sender knows what to keep and what to resend. The ACK also finishes the three-way handshake. In the CBET course HL7 ACK messages confirm that an interface received a message." },
  "ADF": { full: "Automatic document feeder", tip: "The tray on a scanner or printer that feeds a stack of pages.", more: "The ADF handles loose sheets; the flatbed takes books and anything that cannot feed. Misfeeds usually mean worn rollers." },
  "AES": { full: "Advanced Encryption Standard", tip: "The standard symmetric cipher, with 128, 192, or 256-bit keys.", more: "AES encrypts and decrypts with the same key and is fast enough to protect disks, Wi-Fi (WPA2 and WPA3), VPNs, and TLS sessions. AES-128 is secure; AES-256 is used for high-value data. It replaced DES and 3DES." },
  "AHCI": { full: "Advanced Host Controller Interface", tip: "The SATA controller mode that enables native command queuing and hot plug.", more: "A drive running in IDE mode instead of AHCI loses performance and features. Switching modes after Windows is installed can cause a boot failure unless the driver is enabled first." },
  "AIO": { full: "All-in-one", tip: "A liquid CPU cooler with a sealed pump and radiator, or a computer built into its monitor.", more: "AIO coolers move heat to a radiator on the case; AIO computers pack the board into the display. Context tells which." },
  "AM4": { full: "AMD socket AM4", tip: "AMD's PGA socket for Ryzen processors through 2022.", more: "AM4 boards accept a range of Ryzen generations with BIOS updates; the CPU carries the pins." },
  "AM5": { full: "AMD socket AM5", tip: "AMD's current LGA socket for Ryzen processors with DDR5.", more: "AM5 moved the pins into the socket and requires DDR5 memory. It is not compatible with AM4 chips." },
  "AMD": { full: "Advanced Micro Devices", tip: "The other major maker of x86 CPUs and of Radeon graphics.", more: "AMD's Ryzen desktop chips use AM4 (PGA) and AM5 (LGA) sockets. AMD-V is its hardware virtualization feature, matched by Intel's VT-x." },
  "AMD-V": { full: "AMD Virtualization", tip: "AMD's hardware support for running virtual machines.", more: "AMD-V, like Intel VT-x, lets a hypervisor run guests efficiently. It must be enabled in firmware or virtual machines will not start." },
  "AP": { full: "Access point", tip: "The radio that bridges Wi-Fi clients onto the wired network.", more: "An access point turns Wi-Fi frames into Ethernet frames and back. Standalone (autonomous) APs are configured one by one; lightweight APs are managed by a wireless LAN controller. Each AP advertises one or more SSIDs, and clients roam between APs that share an SSID. In the CBET course the same letters also appear in anteroposterior X-ray views; read the context." },
  "API": { full: "Application programming interface", tip: "The defined way one program talks to another, such as the web endpoints a cloud service exposes.", more: "APIs let software request data and actions from other software. Cloud consoles, SDN controllers, and mobile apps all work through APIs. Security concerns include stolen API keys, missing authentication, and rate limiting." },
  "APIPA": { full: "Automatic Private IP Addressing", tip: "The 169.254.x.x address a host gives itself when it cannot reach a DHCP server.", more: "When DHCP fails, Windows and other systems self-assign an address in 169.254.0.0/16 so hosts on the same segment can still talk. Seeing a 169.254 address is the classic sign that a client could not get a lease, which points at the DHCP server, the relay, or the link." },
  "ARM": { full: "Advanced RISC Machine", tip: "The low-power processor design in phones, tablets, and newer laptops.", more: "ARM CPUs use a reduced instruction set and consume little power, which is why phones and Apple silicon Macs use them. Software compiled for x86 needs translation or a native ARM build." },
  "ARP": { full: "Address Resolution Protocol", tip: "Finds the MAC address that goes with a known IPv4 address on the local segment.", more: "When a host knows the IP address of a neighbor but not its MAC address, it broadcasts an ARP request and the owner replies with its MAC. Hosts cache the answer in an ARP table. Because ARP has no authentication, attackers can poison the cache to redirect traffic, which is why switches offer dynamic ARP inspection. IPv6 replaces ARP with Neighbor Discovery." },
  "ATX": { full: "Advanced Technology Extended", tip: "The standard full-size desktop motherboard and power supply form factor, 12 x 9.6 inches.", more: "ATX defines the board size, mounting holes, and rear port layout so cases, boards, and supplies interchange. MicroATX and Mini-ITX are the smaller board sizes; SFX is the small power supply." },
  "B+M": { full: "B and M keyed M.2 module", tip: "An M.2 SSD notched for both B and M key slots, usually a SATA drive.", more: "A B+M keyed module fits either socket type but typically runs at SATA speed. NVMe drives are M key only." },
  "BIOS": { full: "Basic Input/Output System", tip: "The original PC firmware: 16-bit, text setup, MBR disks up to 2 TB.", more: "BIOS initializes hardware, runs the power-on self-test, and hands off to the boot loader. It is limited to MBR disks and four primary partitions and has been replaced by UEFI, which many people still call the BIOS." },
  "BNC": { full: "Bayonet Neill-Concelman connector", tip: "The twist-lock coax connector used on older LANs, test equipment, and CCTV.", more: "BNC connectors lock with a quarter turn. Thin-net Ethernet used them in the 1990s, and they remain on oscilloscopes, signal generators, and some camera systems." },
  "BSOD": { full: "Blue screen of death", tip: "The Windows stop error screen from a driver or hardware fault.", more: "A BSOD shows a stop code and often a driver name. Repeated blue screens point to bad drivers, faulty RAM, or overheating; the stop code is the first clue." },
  "BYOD": { full: "Bring your own device", tip: "Staff use personal phones and laptops for work.", more: "BYOD saves the company money but mixes personal and corporate data on devices the company does not control. Mobile device management, containerization, and acceptable use policies define what the company may do on the device and what happens when someone leaves." },
  "CAS": { full: "Column address strobe (latency)", tip: "The delay in clock cycles before memory returns requested data; lower is faster.", more: "CAS latency, written CL16 for example, is the number of cycles between a request and the data. Along with speed it sets memory performance." },
  "CCFL": { full: "Cold cathode fluorescent lamp", tip: "The backlight in older LCDs, driven by a high-voltage inverter.", more: "A failing inverter or CCFL tube makes the screen very dim while the image is still faintly visible. LED backlights replaced them." },
  "CCTV": { full: "Closed-circuit television", tip: "Security cameras on a private video system.", more: "CCTV runs on coax (RG-59 with BNC) or, for IP cameras, on Ethernet with PoE." },
  "CD": { full: "Compact disc", tip: "Optical media holding about 700 MB.", more: "CDs are read-only (CD-ROM), writable once (CD-R), or rewritable (CD-RW). In the Network+ course CD appears inside CSMA/CD, where it means collision detection." },
  "CEC": { full: "Consumer Electronics Control", tip: "The HDMI feature that lets one remote control several devices.", more: "CEC passes commands over HDMI so a TV remote can control a connected player or sound bar." },
  "CF": { full: "CompactFlash card", tip: "A larger, older flash memory card used in professional cameras and industrial gear.", more: "CompactFlash predates SD. It survives in some professional cameras and equipment; SD and microSD replaced it elsewhere." },
  "CIFS": { full: "Common Internet File System", tip: "An older name for the SMB file-sharing protocol.", more: "CIFS is the SMB 1 era dialect. Modern systems speak SMB 2 and 3; the CIFS name lingers in Linux mount commands." },
  "CL16": { full: "CAS latency 16", tip: "A memory module that answers in 16 clock cycles.", more: "CL16 on a DDR4-3200 label means 16 cycles of latency; a CL14 module of the same speed is slightly faster." },
  "CMOS": { full: "Complementary metal-oxide semiconductor", tip: "The small battery-backed memory that keeps firmware settings and the clock.", more: "The CMOS chip stores BIOS or UEFI settings and time, kept alive by a CR2032 coin cell. A dead cell resets the clock and settings at every boot. Clearing CMOS with a jumper resets a forgotten firmware password." },
  "CNAME": { full: "Canonical name record", tip: "A DNS alias: one name points to another name.", more: "A CNAME says this name is really that other name, so www.example.com might be an alias for the real hostname of a web server. Lookups then continue with the target name. A CNAME cannot sit at the zone apex alongside other records, which is a common configuration mistake." },
  "CPU": { full: "Central processing unit", tip: "The processor that executes instructions.", more: "The CPU's cores, threads, clock speed, and cache set a computer's performance. Sudden CPU spikes are a security indicator for crypto mining or malware. In the A+ course you match its socket (LGA, PGA, AM4, AM5) to the motherboard and keep it cool." },
  "CR2032": { full: "CR2032 coin cell", tip: "The 3 V lithium coin battery that keeps CMOS settings and the clock.", more: "When a PC forgets the time or its firmware settings after being unplugged, replace the CR2032." },
  "CRM": { full: "Customer relationship management", tip: "Software for tracking customers and sales, usually SaaS.", more: "CRM systems such as hosted sales platforms are the exam's example of software as a service." },
  "CRT": { full: "Cathode ray tube", tip: "The old glass-tube monitor; holds dangerous voltage even when unplugged.", more: "CRTs are obsolete but appear in safety questions: they store high voltage, so do not open one or wear a grounding strap while working inside." },
  "CSM": { full: "Compatibility Support Module", tip: "UEFI's legacy mode that boots BIOS-style operating systems.", more: "Enabling CSM lets UEFI firmware boot MBR disks and older operating systems, at the cost of Secure Boot." },
  "DaaS": { full: "Desktop as a service", tip: "VDI hosted by a cloud provider.", more: "DaaS delivers virtual desktops from the cloud with the provider running the infrastructure." },
  "DB9": { full: "D-subminiature 9-pin connector", tip: "The 9-pin serial port connector.", more: "DB9 (properly DE-9) carries RS-232 serial for console cables and legacy equipment." },
  "dBm": { full: "Decibels relative to one milliwatt", tip: "An absolute power level: 0 dBm is 1 mW; Wi-Fi signals are negative numbers such as -65 dBm.", more: "Wi-Fi survey tools report signal strength in dBm; -65 dBm is good, -80 dBm is poor. Every 3 dB halves or doubles the power." },
  "DC": { full: "Direct current", tip: "Current in one direction: batteries, power supply outputs, and PoE.", more: "Computers run on DC at 12, 5, and 3.3 V from the power supply. PoE sends DC over the data cable." },
  "DCI-P3": { full: "Digital Cinema Initiatives P3 color space", tip: "A wide color gamut used for video and film work.", more: "DCI-P3 covers more colors than sRGB. Monitors for video editing are rated by how much of it they show." },
  "DDR": { full: "Double data rate (memory)", tip: "The family of SDRAM generations (DDR3, DDR4, DDR5) that transfer twice per clock cycle.", more: "Each DDR generation has a different notch, voltage, and speed range, so modules are not interchangeable across generations. Match the generation exactly to the board." },
  "DDR3": { full: "Double data rate 3 SDRAM", tip: "The memory generation before DDR4, 240-pin DIMMs at 1.5 V.", more: "DDR3 is legacy. Its modules will not fit DDR4 or DDR5 slots." },
  "DDR4": { full: "Double data rate 4 SDRAM", tip: "The common memory generation: 288-pin DIMM, 260-pin SODIMM, 1.2 V, 2133 to 3200 MT/s.", more: "DDR4 must be matched exactly to the board. A label such as DDR4-3200 gives the speed in megatransfers; PC4-25600 is the same module quoted as bandwidth." },
  "DDR4-2666": { full: "DDR4 at 2666 megatransfers per second", tip: "A slower DDR4 speed rating.", more: "Mixing a 2666 module with a 3200 module runs both at 2666." },
  "DDR4-3200": { full: "DDR4 at 3200 megatransfers per second", tip: "A DDR4 module speed rating.", more: "DDR4-3200 modules transfer 3200 million times per second, equivalent to the PC4-25600 bandwidth label. A board runs all modules at the speed of the slowest." },
  "DDR5": { full: "Double data rate 5 SDRAM", tip: "The current memory generation: higher speed, 1.1 V, on-module voltage regulation.", more: "DDR5 doubles DDR4's bandwidth and requires a DDR5 board such as AM5 or the latest Intel platforms. It is not backward compatible." },
  "DE-15": { full: "D-subminiature E shell, 15 pins", tip: "The formal name of the VGA connector.", more: "DE-15 is the three-row 15-pin D-sub used for VGA, often miscalled DB-15." },
  "DFS": { full: "Dynamic frequency selection", tip: "Wi-Fi channels in the 5 GHz band that must yield to radar.", more: "Some 5 GHz channels are shared with weather and military radar. An access point using a DFS channel must listen for radar and move off the channel if it hears any, which can cause sudden client disconnects. In the A+ course the same letters may also appear for Windows Distributed File System; read the context." },
  "DHCP": { full: "Dynamic Host Configuration Protocol", tip: "Hands out IP addresses, masks, gateways, and DNS servers automatically (UDP 67 and 68).", more: "A DHCP server leases addresses to clients through the DORA exchange: Discover, Offer, Request, Acknowledge. The lease also carries the subnet mask, default gateway, DNS servers, and options such as a TFTP server. Because Discover is a broadcast, a router needs a relay (IP helper) to reach a server on another subnet. Reservations tie a fixed address to a MAC; scopes and exclusions define the pool." },
  "DIMM": { full: "Dual in-line memory module", tip: "The full-size desktop memory stick.", more: "Desktop boards take DIMMs; each DDR generation has a different notch and pin count (DDR4 288 pins, DDR5 288 pins with a different key), so generations do not interchange." },
  "DKIM": { full: "DomainKeys Identified Mail", tip: "Outgoing mail is digitally signed; the public key is published in DNS.", more: "DKIM lets a receiving server verify that a message really came from the domain and was not altered, by checking the signature against the key in a DNS TXT record." },
  "DMARC": { full: "Domain-based Message Authentication, Reporting, and Conformance", tip: "A DNS policy telling receivers what to do with mail that fails SPF or DKIM, and where to send reports.", more: "DMARC ties SPF and DKIM to the visible From address and states a policy: none, quarantine, or reject. Reports show who is sending mail as your domain." },
  "DNS": { full: "Domain Name System", tip: "Translates names such as www.example.com into IP addresses (UDP 53, TCP 53 for zone transfers).", more: "DNS is a distributed database of names. A resolver asks recursive servers, which walk from the root to the top-level domain to the authoritative server for the zone. Record types include A (IPv4), AAAA (IPv6), CNAME (alias), MX (mail), PTR (reverse), TXT (text such as SPF), SRV (service location), NS, and SOA. If a site works by IP address but not by name, DNS is the problem." },
  "DOCSIS": { full: "Data Over Cable Service Interface Specification", tip: "The standard cable modems use to carry internet over the TV coax.", more: "DOCSIS shares bandwidth with the neighborhood, so speeds vary with load. The modem connects with an F-type coax connector." },
  "DORA": { full: "Discover, Offer, Request, Acknowledge", tip: "The four-step DHCP lease exchange.", more: "A client with no address broadcasts a Discover, servers answer with an Offer, the client broadcasts a Request for one offer, and that server confirms with an Acknowledge. Remembering DORA answers most DHCP sequence questions." },
  "DP": { full: "DisplayPort", tip: "The computer-oriented digital video connector with daisy-chaining and high bandwidth.", more: "DisplayPort supports multi-stream to chain monitors and reaches 80 Gb/s in version 2.0. Mini DisplayPort appears on older laptops; USB-C can carry DisplayPort in alternate mode." },
  "DRAM": { full: "Dynamic random-access memory", tip: "The main system memory technology, refreshed constantly.", more: "DRAM stores bits in capacitors that must be refreshed thousands of times a second. It is dense and cheap, which is why it is used for main memory." },
  "DSL": { full: "Digital subscriber line", tip: "Internet over the telephone line through an RJ11 jack; speed falls with distance from the exchange.", more: "DSL uses frequencies above voice on the copper phone line. Filters keep it off the phones. Its speed depends on the loop length." },
  "DSSS": { full: "Direct-sequence spread spectrum", tip: "The spreading technique used by early 2.4 GHz Wi-Fi (802.11b).", more: "DSSS spreads each bit across a wider band using a chipping code, which makes the signal resistant to narrowband interference. It was replaced by OFDM in later Wi-Fi generations." },
  "DVD": { full: "Digital versatile disc", tip: "Optical media holding 4.7 GB, or 8.5 GB dual layer.", more: "DVDs succeeded CDs for software and video. Blu-ray raised capacity to 25 GB per layer." },
  "DVI": { full: "Digital Visual Interface", tip: "The older white digital video connector; DVI-D digital, DVI-A analog, DVI-I both.", more: "DVI carries video but not audio. Single-link tops out around 1920 x 1200; dual-link goes higher. It adapts passively to HDMI and, for DVI-I, to VGA." },
  "DVI-A": { full: "DVI analog", tip: "A DVI connector that carries only an analog VGA-style signal.", more: "DVI-A is rare; it exists to connect analog monitors through a DVI-shaped plug." },
  "DVI-D": { full: "DVI digital", tip: "A DVI connector that carries only a digital signal.", more: "DVI-D adapts to HDMI with a passive adapter but cannot drive a VGA monitor." },
  "DVI-I": { full: "DVI integrated", tip: "A DVI connector carrying both digital and analog signals.", more: "DVI-I ports accept a passive VGA adapter because the analog pins are present." },
  "ECC": { full: "Error-correcting code memory", tip: "Memory that detects and fixes single-bit errors; used in servers and workstations.", more: "ECC RAM adds parity bits so a flipped bit is corrected instead of crashing the system or corrupting data. It needs a board and CPU that support it. In Security+ the same letters mean elliptic curve cryptography; read the context." },
  "EPS": { full: "Entry-level Power Supply specification (CPU power connector)", tip: "The 4-pin or 8-pin 12 V connector near the CPU socket.", more: "The EPS connector feeds the CPU voltage regulators. A board that will not power up with only the 24-pin main connector attached is missing this one." },
  "eSATA": { full: "External SATA", tip: "A SATA port on the outside of the case for external drives.", more: "eSATA gives external drives full SATA speed but needs separate power, which is why USB largely replaced it." },
  "ESD": { full: "Electrostatic discharge", tip: "Static electricity that can destroy chips; prevented with a wrist strap, mat, and antistatic bags.", more: "A static shock you cannot feel can still kill a component. Wear a strap connected to ground, work on an antistatic mat, and keep parts in their bags. Never wear a strap inside a power supply or CRT, which hold lethal voltages." },
  "eSIM": { full: "Embedded SIM", tip: "A SIM built into the phone and provisioned by software.", more: "eSIM profiles are downloaded from the carrier, often via a QR code, so no physical card is needed and several profiles can coexist." },
  "FDM": { full: "Fused deposition modeling", tip: "3D printing that melts plastic filament through a nozzle layer by layer.", more: "FDM printers build parts from filament on a heated bed. Resin (SLA) printers are the other consumer type." },
  "FTP": { full: "File Transfer Protocol", tip: "Plaintext file transfer on TCP 21 (control) and 20 (data); replace with SFTP or FTPS.", more: "FTP sends usernames, passwords, and files in the clear and needs a second connection for data, which complicates firewalls. Active mode has the server connect back to the client; passive mode has the client open both. It survives on legacy systems only." },
  "FTPS": { full: "FTP Secure", tip: "FTP wrapped in TLS, ports 990 and 989 (implicit) or 21 with an upgrade (explicit).", more: "FTPS adds TLS encryption to ordinary FTP. It is different from SFTP, which runs over SSH. Exam questions test whether you know they are separate protocols on separate ports." },
  "GB": { full: "Gigabyte", tip: "About a billion bytes; the unit for RAM, storage, and data caps.", more: "A gigabyte is 1,000 or 1,024 megabytes depending on whether the maker counts in decimal or binary. RAM is sold in GB, and 32-bit systems can address only about 4 GB." },
  "GG45": { full: "GG45 connector", tip: "A backward-compatible Cat 7 and Cat 8 connector that also accepts RJ45 plugs.", more: "GG45 is one of the shielded connectors specified for Cat 7 and Cat 8 cabling. It is rare in practice; most 10 Gbps installations simply use Cat 6A with ordinary RJ45 plugs." },
  "GHz": { full: "Gigahertz", tip: "Billions of cycles per second; CPU clock speed and Wi-Fi band frequency.", more: "A 3.5 GHz CPU ticks 3.5 billion times a second. Wi-Fi uses the 2.4, 5, and 6 GHz bands, where higher frequency means more bandwidth but shorter range and worse wall penetration." },
  "GPS": { full: "Global Positioning System", tip: "Satellite positioning, also used as a stratum 0 time reference.", more: "GPS receivers get both position and extremely accurate time from satellites. Networks use GPS-disciplined clocks as their top-level NTP or PTP reference. Phones use GPS for location, which is also the somewhere-you-are factor in authentication." },
  "GPT": { full: "GUID Partition Table", tip: "The modern disk partition scheme: any disk size, up to 128 partitions, required for UEFI boot.", more: "GPT replaced MBR's 2 TB limit and four-partition limit and stores backup partition tables for resilience. Windows converts a disk with MBR2GPT when moving from BIOS to UEFI." },
  "GPU": { full: "Graphics processing unit", tip: "The processor that renders images; on a card or built into the CPU.", more: "A discrete GPU on a PCIe x16 card needs its own power connectors and drives high resolutions and games. Integrated graphics share the CPU and system memory and suit office work." },
  "HD": { full: "High definition", tip: "Video resolutions of 1280 x 720 (HD) and 1920 x 1080 (Full HD).", more: "Full HD is 1920 x 1080 pixels. QHD is 2560 x 1440 and 4K UHD is 3840 x 2160." },
  "HDD": { full: "Hard disk drive", tip: "Spinning magnetic storage: cheap per terabyte, slower, and fragile.", more: "HDDs spin platters at 5400 or 7200 rpm and read them with a moving head, so they are slow to seek and vulnerable to shock. Clicking, slow response, and S.M.A.R.T. warnings mean replace it and restore from backup." },
  "HDMI": { full: "High-Definition Multimedia Interface", tip: "The common digital video and audio connector for monitors and TVs.", more: "HDMI carries video, audio, and control (CEC) on one cable. HDMI 2.1 reaches 48 Gb/s for 8K. Mini and micro sizes exist for cameras and tablets." },
  "HEPA": { full: "High-efficiency particulate air (filter)", tip: "A filter that traps fine dust; used in vacuums safe for electronics and toner.", more: "Ordinary vacuums blow toner dust through their filters; a HEPA or toner-rated vacuum is required for printer cleanup." },
  "HR": { full: "Human resources", tip: "The department that handles staff records; its documents are the exam's example of sensitive printouts.", more: "HR documents found in a shared printer's output tray point to the need for secure print release." },
  "HSM": { full: "Hardware security module", tip: "A tamper-resistant appliance or card that generates, stores, and uses cryptographic keys.", more: "An HSM performs signing and encryption inside protected hardware so private keys are never exposed, even to administrators. Certificate authorities, payment systems, and cloud key services use them. In the A+ course an HSM header on a motherboard connects such a module." },
  "HTTP": { full: "Hypertext Transfer Protocol", tip: "Web traffic in the clear on TCP 80.", more: "HTTP carries web pages and API calls without encryption, so anything sent can be read on the path. HTTPS on 443 is the secure form, and modern sites redirect to it." },
  "HTTPS": { full: "Hypertext Transfer Protocol Secure", tip: "HTTP inside TLS on TCP 443.", more: "HTTPS encrypts web traffic and lets the browser verify the server's certificate. The padlock means the connection to that server is private, not that the site is honest. DoH also rides on 443." },
  "HVAC": { full: "Heating, ventilation, and air conditioning", tip: "The building's climate systems, which keep server rooms cool and are themselves networked controls.", more: "Equipment fails when HVAC does. Building automation puts HVAC on the network, where it must be segmented like any other IoT." },
  "Hz": { full: "Hertz", tip: "Cycles per second; display refresh rate, AC mains frequency, and signal frequency.", more: "A 60 Hz monitor redraws 60 times a second; gaming panels run 120 to 240 Hz. Mains power is 60 Hz in North America and 50 Hz in much of the world, which matters for equipment and for why a 60 Hz shock makes muscles contract." },
  "IaaS": { full: "Infrastructure as a service", tip: "The provider supplies virtual machines, storage, and networks; you manage the operating system and up.", more: "IaaS rents raw computing. You install and patch the OS and applications while the provider runs the hardware. The exam cue is you manage the OS, they manage the hardware." },
  "ID": { full: "Identifier or identification", tip: "A name or number that uniquely labels a user, device, session, or record.", more: "IDs appear everywhere: user IDs, VLAN IDs, process IDs, patient IDs, and caller ID, which can be spoofed. The exam mostly tests that an ID by itself is not proof of identity." },
  "IDE": { full: "Integrated Drive Electronics", tip: "The legacy parallel ATA drive interface, and the legacy SATA controller mode.", more: "IDE ribbon cables and master/slave jumpers are gone, but the name lives on as the compatibility mode in firmware." },
  "IDS": { full: "Intrusion detection system", tip: "Watches a copy of the traffic and alerts on attacks; cannot block them.", more: "An IDS sits out of band, usually on a SPAN port or tap, and compares traffic against signatures and behavior baselines. It detects and reports but does not stop anything. A host-based IDS does the same on one machine's logs and files." },
  "IMAP": { full: "Internet Message Access Protocol", tip: "Reads mail that stays on the server, synced across devices; TCP 143, secure 993.", more: "IMAP leaves messages on the server and mirrors folders and read status to every client, which is what phones and laptops need. It replaced POP3 for most users." },
  "IOPS": { full: "Input/output operations per second", tip: "A measure of how many small reads and writes a drive handles per second.", more: "IOPS matter for databases and virtual machines more than raw MB/s. NVMe SSDs deliver hundreds of thousands; hard drives only a few hundred." },
  "IoT": { full: "Internet of Things", tip: "Networked devices such as cameras, sensors, thermostats, and smart TVs.", more: "IoT devices are small computers with limited security: default passwords, rare patches, and long lifetimes. They belong on their own segmented network with access limited to what they need." },
  "IP": { full: "Internet Protocol", tip: "The Layer 3 protocol that addresses and routes packets between networks.", more: "IP gives every host a logical address and lets routers forward packets from network to network using that address. Version 4 uses 32-bit addresses written as four numbers; version 6 uses 128-bit addresses written in hex. IP itself is best effort: it does not guarantee delivery, which is why TCP exists above it." },
  "IPS": { full: "In-plane switching", tip: "The LCD panel type with the best color accuracy and viewing angles.", more: "IPS panels are the choice for photo and design work and most quality monitors. They cost more and have lower contrast than VA panels and are slower than TN. In networking courses IPS means intrusion prevention system." },
  "IPv4": { full: "Internet Protocol version 4", tip: "32-bit addresses written as four decimal octets, such as 192.168.1.10.", more: "IPv4 addresses are 32 bits split into four octets. A subnet mask or CIDR prefix says which bits name the network and which name the host. Because there are only about four billion addresses, private ranges plus NAT are used inside organizations. Most subnetting math on the exam is IPv4." },
  "IPv6": { full: "Internet Protocol version 6", tip: "128-bit addresses in eight hex groups; no broadcast, built-in autoconfiguration.", more: "IPv6 uses 128-bit addresses written as hex groups separated by colons, with rules for shortening runs of zeros. There is no broadcast; multicast and neighbor discovery take its place. Hosts can build their own address from a router advertisement (SLAAC). Link-local addresses start with fe80, and the loopback is ::1." },
  "iSCSI": { full: "Internet SCSI", tip: "SCSI storage commands over a TCP/IP network, giving block-level storage without Fibre Channel.", more: "iSCSI lets a server mount a disk on a storage array across ordinary Ethernet, usually on a dedicated storage VLAN. It is the low-cost way to build a SAN." },
  "ISO": { full: "International Organization for Standardization; also an ISO disc image", tip: "The standards body, and the .iso file format that holds a complete disc image.", more: "ISO 9001 is the quality management standard some hospital accreditors use. An ISO file is a disc image you attach to a virtual machine or write to a USB stick to install an operating system." },
  "ISP": { full: "Internet service provider", tip: "The company that connects you to the internet.", more: "The ISP supplies the WAN link, public addresses, and often DNS. Guaranteed uptime from the ISP is an SLA." },
  "IT": { full: "Information technology", tip: "Computers, networks, and the people who run them.", more: "IT is the department and the discipline that runs business systems. On the exam it appears in shadow IT (systems staff set up without approval) and in the contrast with operational technology." },
  "ITX": { full: "Information Technology eXtended (Mini-ITX)", tip: "The 6.7-inch square small-form-factor motherboard size.", more: "Mini-ITX boards fit tiny cases with one expansion slot and share ATX mounting holes, so they fit larger cases too. They are the choice for compact and media PCs." },
  "LAN": { full: "Local area network", tip: "One site's network: a building, floor, or campus that one organization owns and runs.", more: "A LAN is the network inside one location, usually built from switches and Ethernet or Wi-Fi, running at high speed because the organization owns every piece of it. When a question says one office, one building, or one campus, it is describing a LAN. Anything that crosses a provider's link to reach another city is no longer a LAN." },
  "LC": { full: "Lucent connector", tip: "The small square snap-in fiber connector, the most common on modern transceivers.", more: "LC is a small form-factor fiber connector, usually installed as a duplex pair. Its size is why SFP modules use it. It clicks in like a miniature RJ45." },
  "LCD": { full: "Liquid crystal display", tip: "The flat panel that shapes light from a backlight into an image; TN, IPS, and VA are the panel types.", more: "An LCD needs a backlight, LED today and CCFL in old panels with an inverter. It is sharp only at its native resolution. A dim screen with a faint image points to the backlight or inverter, not the panel." },
  "LDAP": { full: "Lightweight Directory Access Protocol", tip: "Queries a directory such as Active Directory for users and groups; TCP 389, secure 636.", more: "LDAP is how applications look up accounts, group memberships, and attributes in a directory. Plain LDAP sends binds in the clear, so LDAPS on 636 or StartTLS should be used. Kerberos handles the actual Windows logon; LDAP handles lookups." },
  "LDAPS": { full: "LDAP Secure", tip: "LDAP over TLS on TCP 636.", more: "LDAPS encrypts directory queries and the credentials used to bind. It is the secure pair for plain LDAP on 389." },
  "LED": { full: "Light-emitting diode", tip: "A small light source: the status lights on a port, the lamp in cheap fiber transmitters, and modern display backlights.", more: "On network gear the link and activity LEDs are the first thing to check. In fiber, LEDs are the low-cost light source for older multimode links. In displays and medical devices LEDs provide backlights and the red and infrared light in pulse oximeter probes." },
  "LGA": { full: "Land grid array", tip: "A CPU socket where the pins are in the socket and the chip has flat contacts (Intel, and AMD AM5).", more: "In an LGA socket bent pins are in the socket, so a damaged socket means a new motherboard. Intel uses LGA 1700 and LGA 1851; AMD moved to LGA with AM5." },
  "LTE": { full: "Long-Term Evolution", tip: "4G cellular data; the workhorse mobile broadband standard.", more: "LTE carries all-IP data at tens of megabits per second and remains the fallback under 5G. Phones, hotspots, and SD-WAN backup links use it." },
  "M.2": { full: "M.2 form factor", tip: "The small card slot for SSDs and wireless cards, keyed B, M, or B+M.", more: "M.2 is a shape, not a speed. An M-keyed slot usually carries PCIe x4 for NVMe; B-keyed or B+M modules are often SATA. Sizes such as 2280 give width and length in millimeters." },
  "MAC": { full: "Media access control (address)", tip: "The 48-bit hardware address burned into a network interface, used at Layer 2.", more: "A MAC address is the physical address of a network card, written as six pairs of hex digits. The first half is the manufacturer code (OUI). Switches build a table of which MAC address is on which port and forward frames by it. MAC addresses only matter within one LAN segment; routers use IP addresses to move packets between networks. In Security+ the same letters can also mean mandatory access control." },
  "macOS": { full: "Mac operating system", tip: "Apple's desktop operating system.", more: "macOS runs on Apple hardware, uses APFS, installs apps from the App Store or disk images, and offers Time Machine backups, Keychain, FileVault encryption, and Spotlight search." },
  "MAN": { full: "Metropolitan area network", tip: "A city-sized network: bigger than a LAN, smaller than a WAN.", more: "A MAN connects several sites within one metro area, for example a hospital's buildings across town joined by fiber that runs under the streets. It is larger than one campus but does not span regions or countries. Exam questions use it as the middle size between LAN and WAN." },
  "MB": { full: "Megabyte", tip: "About a million bytes; file sizes and older media capacities.", more: "A CD holds 700 MB; memory bandwidth and disk speeds are quoted in MB/s." },
  "MBR": { full: "Master boot record", tip: "The legacy partition scheme: disks up to 2 TB, four primary partitions, BIOS boot.", more: "The MBR sits in the first sector and holds the boot code and the partition table. Its limits are why UEFI systems use GPT." },
  "MDIX": { full: "Medium-dependent interface crossover", tip: "Auto-MDIX ports sense the cable and swap transmit and receive pairs, so crossover cables are rarely needed.", more: "Older switch-to-switch and host-to-host links needed a crossover cable. Modern ports detect the pairing and adjust automatically, which is why a straight-through cable works almost everywhere." },
  "MDM": { full: "Mobile device management", tip: "Software that enrolls phones and tablets and enforces policy: passcodes, encryption, apps, remote wipe.", more: "An MDM platform lets the organization configure and secure mobile devices, corporate or personal. It can push settings, restrict apps, locate devices, and wipe a lost one, either fully or just the corporate container." },
  "MHz": { full: "Megahertz", tip: "Millions of cycles per second; memory speed, radio channels, and older CPU clocks.", more: "Memory is rated in MHz or megatransfers, Wi-Fi channels are 20 to 160 MHz wide, and medical telemetry uses the WMTS bands in the 600 and 1400 MHz ranges." },
  "microSD": { full: "Micro Secure Digital card", tip: "The fingernail-sized flash card in phones, cameras, and single-board computers.", more: "microSD cards expand storage in phones and tablets and hold the operating system in devices such as Raspberry Pi. An adapter makes them fit a full SD slot." },
  "MIMO": { full: "Multiple input, multiple output", tip: "Using several antennas at once to send parallel data streams for more speed.", more: "MIMO, introduced with 802.11n, lets an access point and client use multiple antennas to carry separate spatial streams over the same channel. More streams mean higher throughput, which is why an AP is sold as 4x4 or 8x8." },
  "ms": { full: "Millisecond", tip: "One thousandth of a second; latency and response times.", more: "Network latency is quoted in ms. Satellite links add 500 to 600 ms, which hurts voice and interactive traffic. Monitors also quote response time in ms." },
  "mSATA": { full: "Mini-SATA", tip: "A small SATA SSD card used in older laptops before M.2.", more: "mSATA drives look like M.2 cards but are a different, older standard and are not interchangeable." },
  "MT/s": { full: "Megatransfers per second", tip: "The speed rating of memory: millions of data transfers per second.", more: "DDR memory transfers twice per clock cycle, so DDR4-3200 runs 3200 MT/s on a 1600 MHz clock. It is the number on the module label." },
  "MU-MIMO": { full: "Multi-user MIMO", tip: "The access point serves several clients at the same time with separate streams.", more: "Single-user MIMO speeds up one client; MU-MIMO (from 802.11ac Wave 2 and 802.11ax) lets the AP transmit to several clients simultaneously, improving capacity in crowded areas." },
  "MX": { full: "Mail exchanger record", tip: "The DNS record that says which server accepts email for a domain.", more: "MX records list the mail servers for a domain with a priority number; lower is preferred. Sending mail servers look up the MX record of the recipient's domain to know where to deliver. A domain with a broken MX record can send mail but never receives it." },
  "NAS": { full: "Network-attached storage", tip: "A file server appliance that shares folders over the regular network using SMB or NFS.", more: "A NAS is a box of disks with its own small operating system that shares files over the LAN. Clients see shared folders, not raw disks, which is the file-level versus block-level distinction from a SAN. Small offices use a NAS for shared documents and backups." },
  "NAT": { full: "Network address translation", tip: "Rewrites private inside addresses to a public address at the router so many hosts can share it.", more: "NAT lets a network use private RFC 1918 addresses internally while presenting one or a few public addresses to the internet. The router keeps a table mapping each inside connection to the outside address and port. Static NAT maps one address to one; dynamic NAT uses a pool; PAT (port address translation) lets a whole network share one public address by varying ports." },
  "NAT64": { full: "Network address translation 6 to 4", tip: "Lets IPv6-only hosts reach IPv4-only servers by translating between the two.", more: "A NAT64 gateway rewrites IPv6 packets into IPv4 and back. It usually pairs with DNS64, which invents AAAA answers for names that only have A records so the IPv6 client sends traffic toward the gateway. Together they let a network run IPv6 internally while the rest of the world is still on IPv4." },
  "NFC": { full: "Near-field communication", tip: "Very short range radio (about 4 cm) at 13.56 MHz for tap-to-pay and badge readers.", more: "NFC powers contactless payment, transit cards, and quick pairing. Its short range is part of its security." },
  "NFS": { full: "Network File System", tip: "The Unix and Linux file-sharing protocol.", more: "NFS lets a client mount a directory from a server as if it were local. It is the Unix counterpart of SMB and is common on NAS appliances and virtualization hosts." },
  "NIC": { full: "Network interface card", tip: "The adapter that connects a computer to the network, wired or wireless.", more: "A NIC has a MAC address and link lights. Teaming two NICs gives redundancy. A failing NIC, a speed or duplex mismatch, or a bad driver are standard troubleshooting suspects." },
  "NS": { full: "Name server record", tip: "The DNS record listing the authoritative name servers for a zone.", more: "NS records tell the rest of the internet which servers hold the real data for a domain. The parent zone (such as .com) holds NS records delegating your domain to your servers, and your zone lists them again." },
  "NTP": { full: "Network Time Protocol", tip: "Synchronizes clocks across the network (UDP 123); wrong time breaks Kerberos, certificates, and logs.", more: "NTP keeps every device's clock aligned to a reference. Stratum 0 is the reference clock (GPS, atomic), stratum 1 servers connect to it, and each hop adds one. Kerberos fails when clocks differ by more than five minutes, certificates look expired, and logs cannot be correlated. NTS adds authentication. In the CBET course the same letters also name the National Toxicology Program; read the context." },
  "NVMe": { full: "Non-Volatile Memory Express", tip: "The fast SSD interface that talks to PCIe lanes directly, usually in an M.2 slot.", more: "NVMe drives reach several thousand MB/s, many times a SATA SSD's 550 MB/s. An M.2 slot must support NVMe (M key, PCIe lanes) rather than SATA for the drive to work." },
  "OFDMA": { full: "Orthogonal frequency-division multiple access", tip: "Wi-Fi 6 splits a channel into small sub-channels so many clients share it efficiently.", more: "OFDMA divides a channel into resource units that can be assigned to different clients in the same transmission. Many small packets from many devices no longer need to wait for the whole channel, which is why Wi-Fi 6 handles dense environments better." },
  "OLED": { full: "Organic light-emitting diode", tip: "A display whose pixels emit their own light: perfect blacks, thin, but prone to burn-in.", more: "OLED needs no backlight, so black pixels are simply off, giving infinite contrast. Static images can burn in over time, and panels are more expensive than LCD." },
  "OM3": { full: "Optical multimode 3", tip: "Laser-optimized 50 micron multimode fiber, aqua, 10 Gbps to about 300 m.", more: "OM3 is optimized for VCSEL lasers and is the common grade for 10 Gbps inside buildings and data centers." },
  "ONT": { full: "Optical network terminal", tip: "The box that converts the fiber provider's light signal to Ethernet at the customer premises.", more: "The ONT is the fiber equivalent of a cable modem. It sits where the fiber enters and hands an Ethernet port to the router." },
  "OS": { full: "Operating system", tip: "The software that manages hardware and runs applications: Windows, macOS, Linux, iOS, Android.", more: "The OS controls processes, memory, files, and devices. Keeping it patched and hardened is the first endpoint defense. In cloud terms, with IaaS you manage the OS and the provider manages the hardware." },
  "OSI": { full: "Open Systems Interconnection model", tip: "The seven-layer reference model used to describe where a protocol or device does its work.", more: "The OSI model splits networking into seven layers, from Physical (1) up to Application (7). The exam uses it as a vocabulary: a Layer 2 problem is about switching and MAC addresses, a Layer 3 device is a router, and Layer 4 is where TCP and UDP port numbers live. Real protocol stacks such as TCP/IP do not map perfectly onto it, but the layer numbers are still how questions are asked." },
  "PaaS": { full: "Platform as a service", tip: "The provider runs the platform (OS, runtime, database); you deploy code.", more: "PaaS gives developers a managed environment to run applications without administering servers. You bring the code and data; the provider handles patching, scaling, and the runtime." },
  "PAN": { full: "Personal area network", tip: "A network within arm's reach, such as Bluetooth between a phone and earbuds.", more: "A PAN covers one person's space: a few meters at most. Bluetooth, NFC, and a USB tether between a phone and a laptop are all PAN connections. The point of the term is scale, not technology." },
  "PC": { full: "Personal computer", tip: "A desktop or laptop for one user.", more: "The PC is the machine the A+ exam takes apart: motherboard, CPU, RAM, storage, power supply, and ports. In networking questions it is the client behind the phone or on the switch port." },
  "PC4-25600": { full: "PC4-25600 bandwidth label", tip: "The DDR4-3200 speed written as 25,600 MB/s of bandwidth.", more: "Module makers label speed either as megatransfers (DDR4-3200) or as bandwidth (PC4-25600); they describe the same part." },
  "PCI": { full: "Peripheral Component Interconnect", tip: "The older expansion bus; PCIe (PCI Express) is its modern serial successor.", more: "PCIe slots come in x1, x4, x8, and x16 lengths, with x16 for graphics cards and x4 for NVMe drives. A card works in a longer slot. In Security+ PCI refers to the payment card industry; read the context." },
  "PCL": { full: "Printer Command Language", tip: "HP's page description language, fast and common in office printing.", more: "PCL drivers are the default for most business printers. PostScript is the alternative for graphics work. Using the wrong language prints pages of garbage characters." },
  "PDF": { full: "Portable Document Format", tip: "Adobe's fixed-layout document file.", more: "A corrupted PDF stuck in a print queue is a classic cause of a printer that stops printing for everyone until the job is cleared." },
  "PGA": { full: "Pin grid array", tip: "A CPU package with pins on the chip that drop into holes in the socket (AMD AM4).", more: "PGA chips are easy to bend and the pins are on the expensive part. AMD used PGA for AM4 and switched to LGA for AM5." },
  "PIN": { full: "Personal identification number", tip: "A short numeric secret, a something-you-know factor.", more: "A PIN unlocks a phone, a SIM, or a smart card. A password plus a PIN is still one factor because both are things you know." },
  "PJL": { full: "Printer Job Language", tip: "Commands that wrap a print job to set options and switch languages.", more: "A page of text beginning with @PJL means the printer received job control commands it could not interpret, usually a driver problem." },
  "PoE": { full: "Power over Ethernet", tip: "Delivers DC power to devices over the data cable: 802.3af 15.4 W, 802.3at 30 W, 802.3bt 60 to 90 W.", more: "PoE lets phones, access points, and cameras run from the switch port with no separate power supply. A PoE switch (endspan) or an injector (midspan) supplies it. The device negotiates how much it may draw. If a device reboots or will not power up, check the switch's PoE budget and the standard it supports." },
  "POP3": { full: "Post Office Protocol version 3", tip: "Downloads mail to one device and usually deletes it from the server; TCP 110, secure 995.", more: "POP3 pulls messages to a single client and typically removes them from the server, so mail does not sync across devices. It is simple and old; IMAP is the modern choice." },
  "POST": { full: "Power-on self-test", tip: "The firmware's hardware check at power-up; failures show as beep codes or a POST card reading.", more: "POST tests the CPU, memory, and video before anything boots. A board that refuses to POST is signaling a hardware problem, and the beep pattern or a POST card in a slot tells you which." },
  "PPI": { full: "Pixels per inch", tip: "Pixel density; higher is sharper.", more: "Phones exceed 400 PPI; a 27-inch 4K monitor is about 163 PPI. High PPI screens need display scaling to keep text readable." },
  "PRL": { full: "Preferred roaming list", tip: "The carrier's list of networks a phone may use, updated over the air.", more: "PRL updates tell a phone which towers and partner networks to prefer, which is why a carrier may push one to fix roaming problems." },
  "PS": { full: "PostScript", tip: "Adobe's page description language, favored for graphics and publishing.", more: "A page starting with %!PS-Adobe printed as text means a PostScript job went to a printer without PostScript. Not to be confused with the PS_ON pin on a power supply." },
  "PSU": { full: "Power supply unit", tip: "Converts wall AC to the DC voltages a computer needs: 12 V, 5 V, 3.3 V.", more: "The PSU is rated in watts and must cover the CPU, graphics card, and drives with margin. Connectors include the 24-pin main, EPS 4 or 8-pin CPU, PCIe 6 and 8-pin, SATA, and the newer 12VHPWR. Modular supplies let you attach only the cables you need. A PSU that dies of heat, or a paperclip test that will not start it, are classic scenarios." },
  "PTR": { full: "Pointer record", tip: "The reverse DNS record: IP address back to a name.", more: "PTR records live in special reverse zones and answer the question what name belongs to this address. Mail servers and security tools use reverse lookups to check that a connecting address has a matching name. Forward and reverse zones are maintained separately, so they can disagree." },
  "PVC": { full: "Polyvinyl chloride", tip: "The ordinary cable jacket, which gives off toxic smoke; plenum cable is required in air spaces.", more: "PVC-jacketed cable is fine inside walls of one floor, but ceilings and raised floors that carry air need plenum-rated jackets that burn slowly and cleanly." },
  "PWM": { full: "Pulse-width modulation", tip: "Controls fan speed (4-pin headers) and LED brightness by switching power on and off rapidly.", more: "A 4-pin PWM fan header varies duty cycle instead of voltage for precise, quiet fan control. 3-pin headers use voltage control." },
  "PXE": { full: "Preboot Execution Environment", tip: "Booting a computer from the network to install or image an operating system.", more: "PXE lets the NIC fetch a boot image from a server via DHCP and TFTP, which is how deployment tools image many machines at once." },
  "QHD": { full: "Quad high definition", tip: "2560 x 1440 resolution.", more: "QHD has four times the pixels of 720p HD and is a common monitor resolution between Full HD and 4K." },
  "QR": { full: "Quick response code", tip: "The square barcode a phone camera reads.", more: "QR codes carry URLs, Wi-Fi credentials, or eSIM activation data. Attackers also abuse them to send people to malicious sites." },
  "RADIUS": { full: "Remote Authentication Dial-In User Service", tip: "The AAA server behind Wi-Fi Enterprise, VPNs, and 802.1X; UDP 1812 and 1813.", more: "A RADIUS server checks credentials for network access devices (switches, APs, VPN gateways) and tells them what the user is allowed. It encrypts only the password, uses UDP, and combines authentication and authorization, which is why TACACS+ is preferred for device administration." },
  "RAID": { full: "Redundant array of independent disks", tip: "Combining disks for speed, capacity, or fault tolerance: 0 stripe, 1 mirror, 5 stripe with parity, 6 double parity, 10 mirrored stripes.", more: "RAID 0 stripes data across disks for speed with no redundancy; one failure loses everything. RAID 1 mirrors two disks. RAID 5 stripes with one parity block and survives one disk failure (three disks minimum). RAID 6 has two parity blocks and survives two failures (four disks). RAID 10 mirrors pairs then stripes, needing four disks. RAID is availability, not backup." },
  "RAM": { full: "Random-access memory", tip: "The working memory that holds running programs and data; lost at power off.", more: "RAM speed and capacity limit how much a system can do at once. Because it is volatile, forensics collects it first (order of volatility) before the machine is powered down." },
  "RDP": { full: "Remote Desktop Protocol", tip: "Microsoft's remote graphical desktop on TCP 3389.", more: "RDP gives a full Windows desktop over the network. Exposed directly to the internet it is a frequent attack target, so it should sit behind a VPN or gateway with MFA and network level authentication." },
  "RFID": { full: "Radio-frequency identification", tip: "Tags read by radio for badges, inventory, and asset tracking.", more: "RFID badges open doors, and RFID tags track assets. Because tags answer any reader, cloning is possible, so high-security doors combine a badge with a PIN or biometric." },
  "RG-59": { full: "Radio Guide 59 coaxial cable", tip: "Thinner coax for short runs such as CCTV, often with a BNC connector.", more: "RG-59 is older and thinner than RG-6, with more loss over distance. It survives in short analog camera runs and legacy installations." },
  "RG-6": { full: "Radio Guide 6 coaxial cable", tip: "The modern coax grade for cable TV and cable modems, with an F-type connector.", more: "RG-6 has a thicker center conductor and better shielding than RG-59, so it carries cable and satellite signals farther with less loss. The screw-on F-type connector is standard on it." },
  "RGB": { full: "Red, green, blue", tip: "The three color channels of displays and the name of decorative lighting headers.", more: "Every pixel mixes red, green, and blue. Adobe RGB and sRGB are color spaces; RGB headers on a motherboard drive case lighting." },
  "RISC": { full: "Reduced instruction set computer", tip: "A processor design with a small set of simple instructions, as in ARM.", more: "RISC designs trade complex instructions for speed and efficiency. x86 is the complex instruction set family; ARM is RISC." },
  "RJ11": { full: "Registered jack 11", tip: "The small telephone plug, used for analog phone lines and DSL.", more: "RJ11 has six positions with two or four contacts and connects phones, fax machines, and DSL modems to the phone line. It fits loosely into an RJ45 jack, which is a classic cause of a bad connection." },
  "RJ45": { full: "Registered jack 45", tip: "The eight-pin plug on Ethernet twisted-pair cables (properly an 8P8C connector).", more: "RJ45 is the everyday name for the Ethernet plug. It has eight positions and eight contacts, crimped onto four twisted pairs following the T568A or T568B pin-out. The smaller RJ11 is the telephone version." },
  "ROM": { full: "Read-only memory", tip: "Non-volatile memory holding firmware.", more: "ROM and its flash descendants store the BIOS or UEFI so the machine can start before any disk is read." },
  "RPM": { full: "Revolutions per minute", tip: "Rotation speed: hard drive platters at 5400 or 7200, fans, and laboratory centrifuges.", more: "Faster platters mean quicker access. In the CBET course centrifuge speed is set in RPM, but the force that separates samples is the relative centrifugal force, which also depends on the rotor radius." },
  "RS-232": { full: "Recommended Standard 232 serial", tip: "The classic serial port: slow, simple, and still used for console access and legacy devices.", more: "RS-232 uses a DB9 connector on PCs and RJ45 or USB console cables on network gear. Older medical devices and lab analyzers still use it for data output." },
  "RX": { full: "Receive", tip: "The receiving side of a link or the receiving fiber strand.", more: "RX is the receive pin or strand. A TX/RX reversal on fiber, or crossed pairs on copper, means neither side hears the other; loopback tests connect TX to RX to prove a port works." },
  "S.M.A.R.T": { full: "Self-Monitoring, Analysis, and Reporting Technology", tip: "Drive self-diagnostics that warn of impending failure.", more: "S.M.A.R.T. counters track reallocated sectors, temperature, and errors. A warning means back up now and replace the drive." },
  "SaaS": { full: "Software as a service", tip: "Complete applications delivered over the web, such as email and office suites.", more: "With SaaS you log in and use the software; the provider runs everything. It is the model with the least customer responsibility and the least control." },
  "SAN": { full: "Storage area network", tip: "A dedicated network that gives servers block-level access to shared disk arrays.", more: "A SAN is a separate high-speed network, usually Fibre Channel or iSCSI, that connects servers to storage arrays. The server sees SAN storage as if it were a local disk (block level), unlike a NAS, which shares files over the ordinary network. In Security+ the same letters also mean subject alternative name on a certificate; read the context." },
  "SAS": { full: "Serial Attached SCSI", tip: "The enterprise drive interface for servers; faster, dual-ported, and accepts SATA drives.", more: "SAS controllers run in servers and storage arrays, support more drives, and can also connect SATA disks. SAS drives will not work on a SATA controller." },
  "SATA": { full: "Serial ATA", tip: "The standard drive interface: SATA III at 6 Gb/s, 7-pin data and 15-pin power cables.", more: "SATA connects hard drives, SATA SSDs, and optical drives. Revisions 1, 2, and 3 run at 1.5, 3, and 6 Gb/s. A SATA SSD tops out near 550 MB/s. AHCI mode is required for full SSD features; IDE mode is legacy." },
  "SC": { full: "Subscriber connector", tip: "The larger square push-pull fiber connector, common on older gear and patch panels.", more: "SC connectors push in and pull out with a square body. They are bigger than LC and were the standard before small form-factor optics took over." },
  "SCADA": { full: "Supervisory control and data acquisition", tip: "Systems that monitor and control industrial processes such as power, water, and manufacturing.", more: "SCADA gathers data from field sensors and sends commands to controllers over networks that were designed long before internet threats. It runs on old software, cannot tolerate downtime, and must be isolated from the corporate network and the internet." },
  "SCP": { full: "Secure Copy Protocol", tip: "Simple file copying over SSH, TCP 22.", more: "SCP copies files between hosts through an SSH connection with a command-line syntax like cp. It lacks SFTP's directory browsing but is quick for single files." },
  "SCSI": { full: "Small Computer System Interface", tip: "The old parallel drive and peripheral bus; SAS and iSCSI carry its command set today.", more: "SCSI defined the commands storage devices still speak. SAS is its serial successor and iSCSI sends the same commands over IP." },
  "SD": { full: "Secure Digital card", tip: "The flash memory card used in cameras and devices; miniSD and microSD are the smaller sizes.", more: "SD cards come in capacity classes (SDHC, SDXC) and speed classes. microSD with an adapter fits SD slots." },
  "SFP": { full: "Small form-factor pluggable transceiver", tip: "The hot-swappable module that gives a switch port its fiber or copper interface, 1 Gbps.", more: "An SFP slides into a switch and provides the optic or copper port. Choosing the module (SR, LR, copper) chooses the medium and distance. Both ends must match in wavelength and fiber type." },
  "SFTP": { full: "SSH File Transfer Protocol", tip: "File transfer inside an SSH session, TCP 22.", more: "SFTP is not FTP with encryption bolted on; it is a separate protocol carried over SSH. It uses one port, 22, which makes it firewall friendly, and it is the usual secure replacement for FTP." },
  "SFX": { full: "Small form factor power supply", tip: "A compact power supply for small cases.", more: "SFX supplies fit small-form-factor cases where a full ATX supply will not. They provide the same connectors at lower wattage." },
  "SIM": { full: "Subscriber identity module", tip: "The card or embedded chip that identifies a phone to the cellular network.", more: "The SIM holds the subscriber identity and keys. eSIM is the embedded version, provisioned by downloading a profile (often by scanning a QR code). A SIM PIN locks the card; a carrier lock ties the phone to a network." },
  "SLA": { full: "Service level agreement", tip: "The contract stating measurable service commitments, such as 99.9% uptime.", more: "An SLA defines what a provider promises (availability, response time, repair time) and the penalties for missing it. Guaranteed uptime from the ISP is an SLA. Internal IT also uses SLAs for help desk response." },
  "SLAAC": { full: "Stateless address autoconfiguration", tip: "IPv6 hosts build their own address from the router's advertised prefix, no DHCP server needed.", more: "With SLAAC a router advertises the network prefix, and each host appends its own interface identifier (from EUI-64 or a random value) to form a full address. No server keeps state, hence stateless. DHCPv6 can still be used alongside it to hand out DNS servers or to track leases." },
  "SMB": { full: "Server Message Block", tip: "Windows file and printer sharing on TCP 445.", more: "SMB is the protocol behind mapped drives and shared printers. Version 1 is insecure and should be disabled; versions 2 and 3 add signing and encryption. Blocking 445 at the perimeter stops most worm-style spread." },
  "SMT": { full: "Simultaneous multithreading", tip: "One physical core runs two threads at once (Intel calls it Hyper-Threading).", more: "SMT makes each core appear as two logical processors so the core stays busy while one thread waits. Cores are physical; threads are logical." },
  "SMTP": { full: "Simple Mail Transfer Protocol", tip: "Sends email between servers on TCP 25; clients submit on 587 with TLS.", more: "SMTP moves mail toward its destination. Server-to-server delivery uses port 25; client submission uses 587 (or legacy 465) with authentication and TLS. Receiving and reading mail uses POP3 or IMAP, not SMTP." },
  "SNMP": { full: "Simple Network Management Protocol", tip: "Polls and receives alerts from network devices (UDP 161 polls, 162 traps).", more: "An SNMP manager polls agents on devices for values in their MIB, such as interface counters and CPU load, and agents send traps when something happens. Versions 1 and 2c use a plaintext community string; version 3 adds authentication and encryption and is the only version to recommend." },
  "SODIMM": { full: "Small outline DIMM", tip: "The short memory module used in laptops and small PCs.", more: "SODIMMs are about half the length of DIMMs and fit laptops and mini PCs. A laptop with soldered memory cannot be upgraded at all." },
  "SOHO": { full: "Small office, home office", tip: "A small network with a consumer-grade router doing NAT, DHCP, Wi-Fi, and firewall in one box.", more: "SOHO routers are the all-in-one devices the A+ exam configures: change the default password, set WPA3, update firmware, and forward ports only when needed." },
  "SPAN": { full: "Switched port analyzer", tip: "A switch feature that mirrors traffic from ports or VLANs to a monitoring port.", more: "A SPAN session, also called port mirroring, copies frames to a port where a packet capture tool or IDS listens. It is how you see traffic on a switched network without a hardware tap." },
  "SPF": { full: "Sender Policy Framework", tip: "A DNS TXT record listing which servers may send mail for a domain.", more: "Receiving servers check the sender's IP against the domain's SPF record and reject or flag mail from elsewhere. It is one of the three email authentication records with DKIM and DMARC." },
  "SQL": { full: "Structured Query Language", tip: "The language used to query databases; also the name of the servers on TCP 1433 (Microsoft) and 3306 (MySQL).", more: "SQL is how applications read and write relational databases. On the exam it appears as the database server ports and, in security, as SQL injection, where untrusted input is pasted into a query and changes what it does." },
  "SRAM": { full: "Static random-access memory", tip: "Faster memory that needs no refresh, used for CPU cache.", more: "SRAM keeps data with transistors instead of capacitors. It is faster and more expensive than DRAM, so it is used in small amounts for L1 to L3 cache." },
  "SSD": { full: "Solid-state drive", tip: "Flash storage with no moving parts: fast, silent, and shock resistant.", more: "SATA SSDs reach about 550 MB/s; NVMe SSDs several thousand MB/s. TRIM keeps them fast by telling the drive which blocks are free. They wear with writes but far outlast most systems." },
  "SSH": { full: "Secure Shell", tip: "Encrypted remote command-line access and file transfer on TCP 22; replaces Telnet and FTP.", more: "SSH authenticates with passwords or keys and encrypts the whole session. SFTP and SCP ride on it for file copies. Any question about managing a switch or server securely from the command line wants SSH." },
  "SSID": { full: "Service set identifier", tip: "The Wi-Fi network name that access points broadcast and clients join.", more: "The SSID is the human-readable network name, up to 32 characters. One AP can advertise several SSIDs, each mapped to a different VLAN, for example staff and guest. Hiding the SSID stops it appearing in scan lists but is not security, because clients still send it in the clear when they connect." },
  "ST": { full: "Straight tip connector", tip: "The round bayonet twist-lock fiber connector; legacy.", more: "ST connectors twist on like a BNC and are found on older multimode installations. In the CBET course the same letters refer to the ST segment of an ECG; read the context." },
  "STP": { full: "Spanning Tree Protocol", tip: "Blocks redundant switch links so frames cannot loop, while keeping them ready as backups.", more: "Switches with redundant links would forward broadcasts around the loop forever, causing a broadcast storm. STP elects a root bridge, calculates the best path from every switch to it, and blocks the extra ports. If a link fails, blocked ports come back into service. Rapid STP (RSTP, 802.1w) converges in seconds instead of up to 50. In cabling, the same letters mean shielded twisted pair; read the context." },
  "SYN": { full: "Synchronize flag", tip: "The first packet of a TCP handshake.", more: "A client opens a connection with a SYN, the server answers SYN-ACK, and the client completes with ACK. A SYN flood sends the first packet endlessly without finishing, exhausting the server's half-open connection table." },
  "Syslog": { full: "System logging protocol", tip: "Sends device log messages to a central server on UDP 514 with severity levels 0 to 7.", more: "Syslog is the standard way routers, switches, firewalls, and servers ship their logs to one collector or SIEM. Severity runs from 0 (emergency) to 7 (debug). Central logging is what makes troubleshooting and forensics possible." },
  "T568A": { full: "TIA/EIA 568A wiring standard", tip: "One of the two pin-outs for RJ45 cables; green pair on pins 1 and 2.", more: "T568A and T568B define which wire pair goes to which pin in an eight-position plug. A cable with the same standard on both ends is straight-through; A on one end and B on the other is a crossover. Most new installations use T568B, but the rule is to match whatever the site already uses." },
  "T568B": { full: "TIA/EIA 568B wiring standard", tip: "The more common RJ45 pin-out; orange pair on pins 1 and 2.", more: "T568B is the pin-out most installers use. Same standard on both ends makes a straight-through patch cable; mixing A and B makes a crossover cable, which modern auto-MDIX ports no longer need." },
  "TACACS+": { full: "Terminal Access Controller Access-Control System Plus", tip: "Cisco's AAA protocol for device administration on TCP 49; encrypts the whole payload and separates authentication from authorization.", more: "TACACS+ is used to control who can log in to routers and switches and which commands they may run. Compared with RADIUS it uses TCP, encrypts the entire packet, and handles authorization command by command, which suits administrative access rather than user network access." },
  "TB": { full: "Terabyte", tip: "About a trillion bytes; the unit for large drives.", more: "Drives are sold in TB. MBR cannot address more than 2 TB, which is one reason GPT exists." },
  "TCP": { full: "Transmission Control Protocol", tip: "Reliable, ordered, connection-based transport: three-way handshake, acknowledgments, retransmission.", more: "TCP sets up a connection with a SYN, SYN-ACK, ACK handshake, numbers every segment, acknowledges what arrives, and resends what does not. That reliability costs overhead, so it suits web pages, email, and file transfer rather than live voice. Port numbers at Layer 4 identify which application on the host the data is for." },
  "TFTP": { full: "Trivial File Transfer Protocol", tip: "Bare-bones UDP 69 file transfer with no login, used for firmware and config files.", more: "TFTP has no authentication and no directory listing, so it is only for trusted networks: pushing switch firmware, backing up configurations, and network booting (PXE). It should be blocked at the perimeter." },
  "TFX": { full: "Thin form factor power supply", tip: "A slim power supply for low-profile desktop cases.", more: "TFX supplies are long and thin for slim office desktops and small media PCs." },
  "TLD": { full: "Top-level domain", tip: "The last part of a domain name, such as .com or .org.", more: "TLDs are managed by registries under ICANN. Look-alike domains in unusual TLDs are a phishing tell." },
  "TLS": { full: "Transport Layer Security", tip: "The encryption layer under HTTPS and most secure protocols; use 1.2 or 1.3.", more: "TLS authenticates the server with a certificate, agrees session keys, and then encrypts the connection. It replaced SSL, whose versions are all deprecated. TLS 1.0 and 1.1 are also retired. It works at the presentation and session layers in OSI terms and protects web, mail, LDAP, and VPN traffic." },
  "TN": { full: "Twisted nematic", tip: "The fastest and cheapest LCD panel type, with poor viewing angles and color.", more: "TN panels suit competitive gaming for their response time but wash out when viewed from the side." },
  "TPM": { full: "Trusted Platform Module", tip: "A security chip on the motherboard that stores keys and measurements; required for BitLocker and Windows 11.", more: "The TPM holds encryption keys that never leave the chip and records boot measurements so it can refuse to release keys if the firmware or boot loader changed. Full-disk encryption keys, device identity certificates, and attestation all rely on it." },
  "TRIM": { full: "TRIM command", tip: "Tells an SSD which blocks are no longer in use so it can erase them ahead of time.", more: "Without TRIM an SSD slows down as it fills, because it must erase blocks before writing. Modern operating systems send TRIM automatically; never defragment an SSD." },
  "TTL": { full: "Time to live", tip: "A counter that keeps packets and DNS records from living forever.", more: "In an IP header the TTL drops by one at every router, and the packet is discarded at zero, which stops routing loops and is what traceroute exploits. In DNS the TTL is how many seconds a resolver may cache a record before asking again, which is why a changed record can take time to be seen everywhere." },
  "TV": { full: "Television", tip: "A display or broadcast receiver; smart TVs are IoT devices.", more: "Cable TV shares the coax with the cable modem. Smart TVs join the network and should be segmented like other IoT." },
  "TX": { full: "Transmit", tip: "The sending side of a link or the sending fiber strand.", more: "TX marks the transmitting pin or strand. A fiber link works only when TX at one end reaches RX at the other, so a swapped pair is a classic no-link cause." },
  "TXT": { full: "Text record", tip: "A free-text DNS record, used for SPF, DKIM, DMARC, and domain ownership checks.", more: "A TXT record holds arbitrary text under a name. Email authentication policies are published this way: SPF lists allowed senders, DKIM publishes a signing key, and DMARC states what to do with mail that fails. Cloud providers also ask you to add a TXT record to prove you control a domain." },
  "UDP": { full: "User Datagram Protocol", tip: "Connectionless, fast transport with no delivery guarantee; used for voice, video, DNS, DHCP.", more: "UDP sends datagrams without a handshake, without acknowledgments, and without retransmission. That makes it fast and light, which is what real-time voice and video want, since a late packet is useless anyway. DNS queries, DHCP, TFTP, SNMP, and syslog also ride on UDP." },
  "UEFI": { full: "Unified Extensible Firmware Interface", tip: "Modern firmware that replaces BIOS: GPT disks, Secure Boot, mouse-driven setup.", more: "UEFI boots from GPT disks of any size, verifies boot loaders with Secure Boot, and offers a graphical setup. A compatibility mode (CSM) boots legacy BIOS-style systems. Windows 11 requires UEFI with Secure Boot and a TPM." },
  "UHD": { full: "Ultra high definition", tip: "3840 x 2160 resolution, commonly called 4K.", more: "UHD needs more GPU power and bandwidth; HDMI 2.0 or DisplayPort 1.2 and above carry it at 60 Hz." },
  "UPS": { full: "Uninterruptible power supply", tip: "A battery unit that keeps equipment running through a power cut and conditions the power.", more: "A UPS sits between the wall and the equipment, taking over instantly when power fails and giving time to shut down or for a generator to start. It is sized in VA or watts against the load for the runtime needed. In medical settings a UPS covers the transfer gap to emergency power." },
  "US": { full: "United States", tip: "The country; US standards, 60 Hz mains, and US connector conventions.", more: "The US uses 120 V at 60 Hz, T568B wiring by convention, and FCC rules for unlicensed radio bands." },
  "USB": { full: "Universal Serial Bus", tip: "The standard port for peripherals, storage, and charging.", more: "USB versions set speed: 2.0 at 480 Mbps, 3.0 at 5 Gbps, 3.1 at 10 Gbps, 3.2 at 20 Gbps, USB4 at 40 Gbps. Connectors include A, B, mini, micro, and the reversible C. Unknown USB drives are a malware vector, which DLP and device control address." },
  "USB-A": { full: "USB Type-A connector", tip: "The classic flat rectangular USB plug.", more: "USB-A is the host-side connector on most computers and chargers. It is not reversible." },
  "USB-C": { full: "USB Type-C connector", tip: "The small reversible connector that carries USB, DisplayPort, Thunderbolt, and power delivery.", more: "USB-C is a connector shape, not a speed; the cable and port decide whether it does 480 Mbps or 40 Gbps, video, or 100 W charging. Check the port's markings." },
  "USB4": { full: "Universal Serial Bus 4", tip: "The 40 Gbps USB generation over USB-C, based on Thunderbolt.", more: "USB4 carries data, DisplayPort video, and power over one USB-C cable and is compatible with Thunderbolt 3 devices." },
  "UTM": { full: "Unified threat management", tip: "One appliance bundling firewall, IDS/IPS, antivirus, content filtering, and VPN.", more: "UTM devices give small and mid-sized organizations a full security stack in one box. The trade-off is that one device becomes a bottleneck and a single point of failure." },
  "UTP": { full: "Unshielded twisted pair", tip: "The standard copper network cable: four twisted pairs, no shield.", more: "UTP relies on the twists in each pair to cancel interference. Categories set the performance: Cat 5e for 1 Gbps, Cat 6 for 10 Gbps to 55 m, Cat 6A for 10 Gbps to 100 m, Cat 8 for 25 or 40 Gbps to 30 m. It is cheap and easy to terminate, which is why it is the default." },
  "VA": { full: "Vertical alignment", tip: "An LCD panel type with high contrast and deep blacks, slower than IPS.", more: "VA panels sit between TN and IPS: better contrast than IPS, better color than TN, but slower response. In power contexts VA means volt-ampere; read the context." },
  "VAC": { full: "Volts AC", tip: "An alternating-current voltage rating, such as 120 VAC.", more: "Power supplies list their input as a VAC range; the voltage selector must match the country." },
  "VCSEL": { full: "Vertical-cavity surface-emitting laser", tip: "The cheap laser used in multimode fiber transceivers.", more: "VCSELs are small, inexpensive lasers that drive OM3 and OM4 multimode fiber for short-reach links. Single-mode fiber needs more precise, more expensive lasers." },
  "VDI": { full: "Virtual desktop infrastructure", tip: "User desktops run as virtual machines in the data center; the user connects with a thin client.", more: "VDI centralizes desktops for security and management. The endpoint only needs a display protocol client, so a lost laptop holds no data." },
  "VGA": { full: "Video Graphics Array", tip: "The blue 15-pin analog video connector.", more: "VGA carries analog video only, no audio, and gets fuzzy over long cables and at high resolutions. It survives on projectors and older equipment." },
  "VLAN": { full: "Virtual local area network", tip: "A logical LAN on a switch: ports in different VLANs are separate broadcast domains.", more: "A VLAN splits one physical switch into several logical switches. Ports in VLAN 10 cannot talk to ports in VLAN 20 without a router or Layer 3 switch, which contains broadcasts and separates traffic such as voice, data, and guests. Trunk links carry many VLANs between switches using 802.1Q tags. A native VLAN is the untagged one on a trunk, and a voice VLAN lets a phone tag its traffic while the PC behind it stays untagged." },
  "VM": { full: "Virtual machine", tip: "A complete computer running as software on a hypervisor.", more: "A VM has its own operating system and virtual hardware but shares the physical host with others. Type 1 hypervisors run on bare metal; type 2 run on a host OS. VM escape, where code in a guest reaches the host, is the serious virtualization vulnerability; VM sprawl is the management one." },
  "VNC": { full: "Virtual Network Computing", tip: "A cross-platform remote desktop protocol.", more: "VNC shares a screen and control across Windows, macOS, and Linux. It should be tunneled or protected because basic VNC has weak security." },
  "VoIP": { full: "Voice over IP", tip: "Telephone calls carried as packets on the data network.", more: "VoIP replaces separate phone wiring with IP phones on the LAN, usually on their own voice VLAN with QoS so speech is not delayed behind downloads. SIP signals the calls and RTP carries the audio. Latency, jitter, and packet loss are what degrade call quality." },
  "VPN": { full: "Virtual private network", tip: "An encrypted tunnel across an untrusted network such as the internet.", more: "A VPN makes a remote user or site appear to be on the private network by encrypting traffic between the endpoints. Site-to-site VPNs join offices, usually with IPsec; remote-access VPNs connect individual users with IPsec or TLS clients. Split tunneling sends only corporate traffic through the tunnel; full tunneling sends everything." },
  "VRAM": { full: "Video RAM", tip: "The memory on a graphics card that holds frames and textures.", more: "VRAM capacity limits the resolution and detail a GPU can handle. Integrated graphics borrow system RAM instead." },
  "VT": { full: "Virtualization technology", tip: "Intel's hardware virtualization support, enabled in firmware.", more: "Intel VT-x, like AMD-V, must be on for hypervisors to run. In the CBET course VT means ventricular tachycardia; read the context." },
  "WAN": { full: "Wide area network", tip: "Connects LANs across cities or countries, usually over links leased from a provider.", more: "A WAN joins sites that are far apart. Because the organization cannot run its own cable between cities, it rents circuits or internet connections from a carrier, which is why WAN links are slower and cost per month. The internet is the largest WAN. Routers sit at the edge of each site to send traffic across the WAN." },
  "Wi-Fi": { full: "Wireless fidelity", tip: "The trade name for IEEE 802.11 wireless networking.", more: "Wi-Fi is the brand the Wi-Fi Alliance gives to interoperable 802.11 equipment. Generations are numbered: Wi-Fi 4 is 802.11n, Wi-Fi 5 is 802.11ac, Wi-Fi 6 and 6E are 802.11ax (6E adds the 6 GHz band), and Wi-Fi 7 is 802.11be. Bands are 2.4 GHz (range, interference), 5 GHz (speed, more channels), and 6 GHz." },
  "WISP": { full: "Wireless internet service provider", tip: "An ISP that delivers internet by fixed wireless from a tower to an antenna on the building.", more: "WISPs serve rural areas where cable and fiber do not reach. Line of sight to the tower is required." },
  "WLAN": { full: "Wireless local area network", tip: "A LAN delivered over Wi-Fi instead of cables.", more: "A WLAN is the same idea as a LAN, but the clients connect by radio to access points instead of by cable to a switch. The access points still plug into the wired LAN, so a WLAN is an extension of the LAN rather than a separate network. Wi-Fi is the family of standards (IEEE 802.11) that most WLANs use." },
  "WPA2": { full: "Wi-Fi Protected Access 2", tip: "Wi-Fi security using AES with CCMP; still common and acceptable.", more: "WPA2 replaced TKIP with AES-CCMP encryption. Personal mode uses a pre-shared passphrase; Enterprise mode authenticates each user through 802.1X and RADIUS. Its weakness is that a captured handshake can be attacked offline with password guessing, which WPA3 fixes." },
  "WPA3": { full: "Wi-Fi Protected Access 3", tip: "The current Wi-Fi security standard: SAE in Personal mode, stronger encryption, protected management frames.", more: "WPA3 Personal replaces the pre-shared key handshake with SAE (simultaneous authentication of equals), which stops offline password cracking and adds forward secrecy. Enterprise mode still uses 802.1X. Protected management frames are mandatory, blocking deauthentication attacks." },
  "WPS": { full: "Wi-Fi Protected Setup", tip: "The push-button or PIN method for joining Wi-Fi; its PIN mode is insecure and should be disabled.", more: "WPS PIN can be brute-forced in hours, exposing the network passphrase. Turn it off on SOHO routers." },
  "ZIF": { full: "Zero insertion force", tip: "A socket or connector that clamps without pushing, used for CPUs and laptop ribbon cables.", more: "ZIF sockets have a lever that locks the chip in place; laptop keyboards and displays connect with ZIF ribbon connectors that a small latch releases." }
};
// Uppercase words in the course text that are not acronyms (emphasis, registry key names, model numbers, formula symbols).
FRA.acronymIgnore = ["BEST","ESC","FIRST","II","III","MOST","NEXT","ONLY","RE","RW"];
